easings.py:
"""The easing curves — the shape of a tween's motion.

A tween without one moves at a flat, constant rate, which is the single
motion that reads as "a computer did this". `easeOut...` arrives slowing
down, which is what most things in life do; `easeOutBack` and
`easeOutElastic` overshoot and spring back.

Every curve maps 0–1 to 0–1, is exactly 0 at 0 and exactly 1 at 1, and is
named as Kaplay names it, so a curve looked up in Kaplay's documentation is
the curve you get here. The formulas are the standard ones from
easings.net, which is where Kaplay's came from too.

Reached as an object — `easings.easeOutBounce` — rather than as thirty-one
loose names, because that is how Kaplay spells it and because
`from kaplay import *` should not put `easeInOutQuint` in a student's
namespace.
"""
import math

_C1 = 1.70158
_C2 = _C1 * 1.525
_C3 = _C1 + 1
_C4 = 2 * math.pi / 3
_C5 = 2 * math.pi / 4.5


def linear(t):
    return t


def easeInSine(t):
    return 1 - math.cos(t * math.pi / 2)


def easeOutSine(t):
    return math.sin(t * math.pi / 2)


def easeInOutSine(t):
    return -(math.cos(math.pi * t) - 1) / 2


def easeInQuad(t):
    return t * t


def easeOutQuad(t):
    return 1 - (1 - t) ** 2


def easeInOutQuad(t):
    return 2 * t * t if t < 0.5 else 1 - (-2 * t + 2) ** 2 / 2


def easeInCubic(t):
    return t ** 3


def easeOutCubic(t):
    return 1 - (1 - t) ** 3


def easeInOutCubic(t):
    return 4 * t ** 3 if t < 0.5 else 1 - (-2 * t + 2) ** 3 / 2


def easeInQuart(t):
    return t ** 4


def easeOutQuart(t):
    return 1 - (1 - t) ** 4


def easeInOutQuart(t):
    return 8 * t ** 4 if t < 0.5 else 1 - (-2 * t + 2) ** 4 / 2


def easeInQuint(t):
    return t ** 5


def easeOutQuint(t):
    return 1 - (1 - t) ** 5


def easeInOutQuint(t):
    return 16 * t ** 5 if t < 0.5 else 1 - (-2 * t + 2) ** 5 / 2


def easeInExpo(t):
    return 0 if t == 0 else 2 ** (10 * t - 10)


def easeOutExpo(t):
    return 1 if t == 1 else 1 - 2 ** (-10 * t)


def easeInOutExpo(t):
    if t == 0:
        return 0
    if t == 1:
        return 1
    return 2 ** (20 * t - 10) / 2 if t < 0.5 else (2 - 2 ** (-20 * t + 10)) / 2


def easeInCirc(t):
    return 1 - math.sqrt(1 - t * t)


def easeOutCirc(t):
    return math.sqrt(1 - (t - 1) ** 2)


def easeInOutCirc(t):
    if t < 0.5:
        return (1 - math.sqrt(1 - (2 * t) ** 2)) / 2
    return (math.sqrt(1 - (-2 * t + 2) ** 2) + 1) / 2


def easeInBack(t):
    return _C3 * t ** 3 - _C1 * t * t


def easeOutBack(t):
    return 1 + _C3 * (t - 1) ** 3 + _C1 * (t - 1) ** 2


def easeInOutBack(t):
    if t < 0.5:
        return ((2 * t) ** 2 * ((_C2 + 1) * 2 * t - _C2)) / 2
    return ((2 * t - 2) ** 2 * ((_C2 + 1) * (t * 2 - 2) + _C2) + 2) / 2


def easeInElastic(t):
    if t == 0:
        return 0
    if t == 1:
        return 1
    return -(2 ** (10 * t - 10)) * math.sin((t * 10 - 10.75) * _C4)


def easeOutElastic(t):
    if t == 0:
        return 0
    if t == 1:
        return 1
    return 2 ** (-10 * t) * math.sin((t * 10 - 0.75) * _C4) + 1


def easeInOutElastic(t):
    if t == 0:
        return 0
    if t == 1:
        return 1
    if t < 0.5:
        return -(2 ** (20 * t - 10) * math.sin((20 * t - 11.125) * _C5)) / 2
    return (2 ** (-20 * t + 10) * math.sin((20 * t - 11.125) * _C5)) / 2 + 1


def easeOutBounce(t):
    n1, d1 = 7.5625, 2.75
    if t < 1 / d1:
        return n1 * t * t
    if t < 2 / d1:
        t -= 1.5 / d1
        return n1 * t * t + 0.75
    if t < 2.5 / d1:
        t -= 2.25 / d1
        return n1 * t * t + 0.9375
    t -= 2.625 / d1
    return n1 * t * t + 0.984375


def easeInBounce(t):
    return 1 - easeOutBounce(1 - t)


def easeInOutBounce(t):
    if t < 0.5:
        return (1 - easeOutBounce(1 - 2 * t)) / 2
    return (1 + easeOutBounce(2 * t - 1)) / 2


class _Easings:
    """The curves, as attributes, with a readable error for a typo.

    A misspelled curve would otherwise be an AttributeError naming a module,
    which tells a student nothing about which names exist.
    """

    def __getattr__(self, name):
        raise AttributeError(
            "No easing called %r. They are named easeIn/easeOut/easeInOut "
            "plus one of Sine, Quad, Cubic, Quart, Quint, Expo, Circ, Back, "
            "Elastic, Bounce — or easings.linear for no easing at all." % name
        )


easings = _Easings()
for _name, _fn in list(globals().items()):
    if _name.startswith("ease") or _name == "linear":
        setattr(easings, _name, _fn)

#: Every curve by name, for anything that wants to enumerate them.
ALL = {n: getattr(easings, n) for n in dir(easings) if not n.startswith("_")}

engine.py:
"""The engine singleton. kaplay(...) creates it and starts the game the
moment the rest of the script finishes running — there is no run() call
anywhere in the Kaplay guide.

On native CPython, atexit gets us this for free: kaplay() registers the
frame loop and it fires once your script's top level finishes. Under
pygbag (sys.platform == "emscripten"), that trick is unavailable — pygbag
replaces the stdlib atexit module with its own (support/cross/aio/atexit.py
in pygbag 0.9.3), and that replacement has a real bug (register() closes
over an undefined `arg` instead of `args`), so calling atexit.register()
there raises NameError immediately. We detect that platform and skip
atexit entirely; the web build's auto-generated main.py wrapper (see
tools/build_web.py) imports your script as a module — which runs its
whole top level, exactly like atexit firing after it — and then calls
run_async() explicitly itself, the way every pygbag example does."""
from __future__ import annotations
import asyncio
import sys
import random as _random

import pygame

from .vec2 import Vec2
from .gameobj import GameObj
from .assets import AssetManager
from .events import EventManager
from .timers import TimerManager
from .camera import Camera
from .physics import PhysicsSystem, CollisionSystem
from .render import RenderSystem
from .debugmod import debug

_engine: "Engine | None" = None


def current_engine() -> "Engine":
    if _engine is None:
        raise RuntimeError("kaplay(...) must run before anything else in a Kaplay script")
    return _engine


class SoundHandle:
    def __init__(self, sound, loop=False, paused=False, volume=1.0):
        self._channel = None
        self._volume = volume
        self._paused = paused
        if sound is not None:
            self._channel = sound.play(loops=-1 if loop else 0)
            if self._channel:
                self._channel.set_volume(volume)
                if paused:
                    self._channel.pause()

    @property
    def paused(self):
        return self._paused

    @paused.setter
    def paused(self, value):
        self._paused = value
        if self._channel:
            if value:
                self._channel.pause()
            else:
                self._channel.unpause()

    @property
    def volume(self):
        return self._volume

    @volume.setter
    def volume(self, value):
        self._volume = value
        if self._channel:
            self._channel.set_volume(value)


class Engine:
    def __init__(self, width=800, height=600, background=(0, 0, 0)):
        global _engine
        _engine = self

        pygame.init()
        try:
            pygame.mixer.init()
        except pygame.error:
            pass  # no audio device (e.g. headless/CI) — sounds become silent no-ops

        self._width = width
        self._height = height
        self._background = tuple(background)
        self.screen = pygame.display.set_mode((width, height))
        pygame.display.set_caption("kaplay")
        self.clock = pygame.time.Clock()

        self.assets = AssetManager()
        self.events = EventManager()
        self.timers = TimerManager()
        self.camera = Camera(width, height)
        self.physics = PhysicsSystem()
        self.collision = CollisionSystem()
        self.render = RenderSystem()

        self._objs: list[GameObj] = []
        self._scenes: dict[str, callable] = {}
        self._current_scene = None
        self._dt = 0.0
        # Game time, not wall time: it advances with the frames, so it stops
        # when the game does. A sine wave driven by wall time jumps when a
        # paused game resumes.
        self._elapsed = 0.0
        self._running = True
        self._started = False
        self._font_cache = {}
        self.is_web = sys.platform == "emscripten"

        if not self.is_web:
            # Native only — see the module docstring for why this is
            # unsafe under pygbag's own atexit replacement.
            import atexit
            atexit.register(self._atexit_run)

    # ---- values ------------------------------------------------------------

    def width(self):
        return self._width

    def height(self):
        return self._height

    def center(self) -> Vec2:
        return Vec2(self._width / 2, self._height / 2)

    def dt(self):
        return self._dt

    def elapsed(self):
        return self._elapsed

    def mousePos(self) -> Vec2:
        x, y = pygame.mouse.get_pos()
        return Vec2(x, y)

    def toWorld(self, screen_pos) -> Vec2:
        return self.camera.screen_to_world(screen_pos)

    def setGravity(self, n):
        self.physics.gravity = n

    def setBackground(self, r, g, b):
        self._background = (r, g, b)

    def setCamPos(self, pos):
        self.camera.setPos(pos)

    def setCamScale(self, n):
        self.camera.setScale(n)

    def shake(self, n=8):
        self.camera.shake(n)

    def _get_font(self, size):
        f = self._font_cache.get(size)
        if f is None:
            f = pygame.font.SysFont(None, size)
            self._font_cache[size] = f
        return f

    # ---- object tree ---------------------------------------------------------

    def add(self, comp_list) -> GameObj:
        obj = GameObj(comp_list)
        obj._engine = self
        self._register(obj)
        return obj

    def _register(self, obj: GameObj):
        self._objs.append(obj)

    def _unregister(self, obj: GameObj):
        try:
            self._objs.remove(obj)
        except ValueError:
            pass

    def get(self, tag: str):
        return [o for o in self._objs if o.exists() and o.is_(tag)]

    # ---- scenes ----------------------------------------------------------

    def scene(self, name, fn):
        self._scenes[name] = fn

    def go(self, name, *args):
        if name not in self._scenes:
            raise KeyError(
                f"no scene called {name!r} — register it with scene({name!r}, fn) first"
            )
        self._clear_scene()
        self._current_scene = name
        self._scenes[name](*args)

    def _clear_scene(self):
        for obj in list(self._objs):
            obj.destroy()
        self._objs.clear()
        self.events.clear()
        self.timers.clear()
        self.camera = Camera(self._width, self._height)

    # ---- main loop ---------------------------------------------------------

    def _atexit_run(self):
        if self._started:
            return
        self.run()

    def run(self):
        """Starts the frame loop by driving it with a fresh asyncio.run().
        On native, kaplay scripts never need to call this themselves — it
        fires automatically once the script body finishes (see the atexit
        registration in __init__) — but it's safe (and a no-op the second
        time) to call explicitly too. Not for use under pygbag: the web
        build's generated main.py wrapper awaits run_async() directly
        instead, inside the asyncio.run() IT owns (see tools/build_web.py)."""
        if self._started:
            return
        try:
            asyncio.run(self.run_async())
        finally:
            pygame.quit()

    async def run_async(self):
        """The coroutine form of run() — awaits the frame loop directly,
        without starting its own asyncio.run(). This is what the pygbag
        web build's main.py wrapper calls, since pygbag needs to own the
        outermost asyncio.run() itself."""
        if self._started:
            return
        self._started = True
        await self._main_loop()

    async def _main_loop(self):
        import os
        max_frames = int(os.environ.get("KAYPY_TEST_MAX_FRAMES", "0")) or None
        frame_count = 0
        while self._running:
            pg_events = pygame.event.get()
            for e in pg_events:
                if e.type == pygame.QUIT:
                    self._running = False
                elif e.type == pygame.KEYDOWN and e.key == pygame.K_F1:
                    debug.inspect = not debug.inspect
            if not self._running:
                break

            # Native: tick(60) sleeps to pace the loop at 60fps. Web: the
            # browser already paces us (each `await asyncio.sleep(0)`
            # below lands on the next animation frame), and tick(60)'s
            # sleep can't yield to the browser, so it just burns the main
            # thread and makes frame times *less* even — measured in a
            # real build, dt alternated between 16ms and the 50ms cap
            # below. So on web just measure, don't pace.
            elapsed = self.clock.tick() if self.is_web else self.clock.tick(60)
            self._dt = min(elapsed / 1000.0, 0.05)
            self._elapsed += self._dt

            self.events.process_pygame_events(pg_events, self._objs)
            self.events.run_update_handlers(self._objs)

            for obj in list(self._objs):
                if not obj.exists():
                    continue
                for comp in list(obj._comps.values()):
                    comp.update(obj)
                if "update" in obj._event_handlers:
                    obj._fire("update")

            self.timers.update(self._dt)
            # Movement and collision run together, in as many substeps as
            # it takes to keep anything from jumping clean over a wall it
            # should have hit (see PhysicsSystem.substeps_for). Normal
            # frames need exactly one, so this costs nothing until
            # something is genuinely moving fast.
            substeps = self.physics.substeps_for(self._objs, self._dt)
            sub_dt = self._dt / substeps
            for _ in range(substeps):
                self.physics.step(self._objs, sub_dt)
                self.collision.step(self._objs)

            self.screen.fill(self._background)
            self.render.draw(self._objs, self.screen, self.camera, debug.inspect)
            pygame.display.flip()

            frame_count += 1
            shot_at = os.environ.get("KAYPY_SCREENSHOT_AT")
            shot_path = os.environ.get("KAYPY_SCREENSHOT_PATH")
            if shot_at and shot_path and frame_count == int(shot_at):
                pygame.image.save(self.screen, shot_path)
            if max_frames and frame_count >= max_frames:
                self._running = False

            await asyncio.sleep(0)


def rand(a=1.0, b=None):
    if b is None:
        return _random.uniform(0, a)
    return _random.uniform(a, b)


def randi(a=1, b=None):
    if b is None:
        return _random.randint(0, a)
    return _random.randint(a, b)


def choose(seq):
    return _random.choice(seq)

events.py:
"""Input handling: onKeyDown (held, every frame) / onKeyPress (once per
press) / onKeyRelease (once per release), onClick (anywhere), and the
plain per-frame onUpdate / tagged onUpdate("tag", action)."""
import pygame
from .callutil import call_flexible

_LETTERS = "abcdefghijklmnopqrstuvwxyz"
_DIGITS = "0123456789"

# Built lazily, on first use, rather than at module import time: native
# pygame-ce's pygame.K_LEFT etc. are plain constants, available the moment
# you `import pygame`, before pygame.init() ever runs — but pygbag's WASM
# build of pygame apparently doesn't populate them until after init(), and
# `import kaplay` reaches this module (via engine.py's `from .events import
# EventManager`) well before a script's own kaplay() call gets to run
# pygame.init(). Building the map eagerly here crashed every web export
# with `AttributeError: module 'pygame' has no attribute 'K_LEFT'` before a
# single line of the game script ran. resolve_key()/key_name() are only
# ever called from on_key_down/on_key_press/on_key_release (registered
# after kaplay() runs) or from the frame loop (which only starts after
# kaplay() runs), so building on first call is always safe.
_KEY_MAP = None
_REVERSE_KEY_MAP = None


def _ensure_key_maps():
    global _KEY_MAP, _REVERSE_KEY_MAP
    if _KEY_MAP is not None:
        return
    _KEY_MAP = {
        "left": pygame.K_LEFT, "right": pygame.K_RIGHT,
        "up": pygame.K_UP, "down": pygame.K_DOWN,
        "space": pygame.K_SPACE, "enter": pygame.K_RETURN, "return": pygame.K_RETURN,
        "escape": pygame.K_ESCAPE, "tab": pygame.K_TAB,
        "shift": pygame.K_LSHIFT, "ctrl": pygame.K_LCTRL, "control": pygame.K_LCTRL,
        "alt": pygame.K_LALT, "backspace": pygame.K_BACKSPACE,
    }
    for _c in _LETTERS:
        _KEY_MAP[_c] = getattr(pygame, f"K_{_c}")
    for _d in _DIGITS:
        _KEY_MAP[_d] = getattr(pygame, f"K_{_d}")
    _REVERSE_KEY_MAP = {code: name for name, code in _KEY_MAP.items()}


def resolve_key(name: str) -> int:
    _ensure_key_maps()
    key = name.lower()
    if key not in _KEY_MAP:
        raise KeyError(f"unknown key name {name!r}")
    return _KEY_MAP[key]


def key_name(code: int) -> str:
    _ensure_key_maps()
    return _REVERSE_KEY_MAP.get(code, str(code))


class EventManager:
    def __init__(self):
        self.key_down_handlers = []
        # (tag_a, tag_b, fn) — the object-free onCollide, fired by
        # CollisionSystem when a NEW touch begins between two tags.
        self.collide_tag_handlers = []
        self.key_press_handlers = []
        self.key_release_handlers = []
        self.click_handlers = []
        self.update_handlers = []  # (tag_or_None, fn)

    def clear(self):
        self.key_down_handlers.clear()
        self.collide_tag_handlers.clear()
        self.key_press_handlers.clear()
        self.key_release_handlers.clear()
        self.click_handlers.clear()
        self.update_handlers.clear()

    def on_collide_tags(self, tag_a, tag_b, fn):
        self.collide_tag_handlers.append((tag_a, tag_b, fn))
        return fn

    def fire_tag_collision(self, a, b):
        """A new touch between a and b — tell anyone watching for the pair.

        Checked both ways round, so onCollide("bullet", "enemy") fires
        whichever of the two the collision system happened to look at first.
        The handler always gets them in the order the tags were named.
        """
        for tag_a, tag_b, fn in list(self.collide_tag_handlers):
            if a.is_(tag_a) and b.is_(tag_b):
                call_flexible(fn, a, b)
            elif b.is_(tag_a) and a.is_(tag_b):
                call_flexible(fn, b, a)

    def on_key_down(self, key, fn):
        self.key_down_handlers.append((resolve_key(key), fn))
        return fn

    def on_key_press(self, key, fn):
        self.key_press_handlers.append((resolve_key(key), fn))
        return fn

    def on_key_release(self, key, fn):
        self.key_release_handlers.append((resolve_key(key), fn))
        return fn

    def on_click(self, fn):
        self.click_handlers.append(fn)
        return fn

    def on_update(self, *args):
        if len(args) == 1:
            self.update_handlers.append((None, args[0]))
            return args[0]
        tag, fn = args
        self.update_handlers.append((tag, fn))
        return fn

    def process_pygame_events(self, pg_events, objs):
        for e in pg_events:
            if e.type == pygame.KEYDOWN:
                for code, fn in self.key_press_handlers:
                    if code == e.key:
                        call_flexible(fn, key_name(code))
            elif e.type == pygame.KEYUP:
                for code, fn in self.key_release_handlers:
                    if code == e.key:
                        call_flexible(fn, key_name(code))
            elif e.type == pygame.MOUSEBUTTONDOWN and e.button == 1:
                for fn in self.click_handlers:
                    call_flexible(fn)
                for obj in objs:
                    if (obj.exists() and obj.has("area")
                            and "click" in obj._event_handlers
                            and obj.comp("area").isHovering()):
                        obj._fire("click")

        pressed = pygame.key.get_pressed()
        for code, fn in self.key_down_handlers:
            if pressed[code]:
                call_flexible(fn, key_name(code))

    def run_update_handlers(self, objs):
        for tag, fn in self.update_handlers:
            if tag is None:
                call_flexible(fn)
            else:
                for obj in objs:
                    if obj.exists() and obj.is_(tag):
                        call_flexible(fn, obj)

gameobj.py:
"""GameObj: the entity, built out of a list of components (and tags).

Kaplay literally merges each component's properties onto the object
(Object.assign). We fake that with attribute delegation in __getattr__,
which is also what produces the "has no attribute" error the guide's
troubleshooting section describes when a component is missing.
"""
from __future__ import annotations

_next_id = 0


def _new_id():
    global _next_id
    _next_id += 1
    return _next_id


class Comp:
    """Base class for all components. Subclasses set `id` and may
    implement add/update/draw hooks, plus any methods/attributes that
    should appear directly on the owning GameObj.
    """
    id: str = ""

    def add(self, obj: "GameObj"):
        """Called once, when the component is attached to obj."""

    def update(self, obj: "GameObj"):
        """Called every frame, if the engine has one running."""

    def draw(self, obj: "GameObj", ctx):
        """Called every frame during rendering."""

    def destroy(self, obj: "GameObj"):
        """Called once, when obj is destroyed."""


class GameObj:
    def __init__(self, comp_list=None):
        self._id = _new_id()
        self._comps: dict[str, Comp] = {}
        self.tags: set[str] = set()
        self.children: list["GameObj"] = []
        self.parent: "GameObj | None" = None
        self._destroyed = False
        self._engine = None  # set by Engine.add / obj.add
        self._event_handlers: dict[str, list] = {}
        if comp_list:
            self.use_all(comp_list)

    # ---- component wiring -------------------------------------------------

    def use(self, comp):
        """Attach a single component or tag string."""
        if isinstance(comp, str):
            self.tags.add(comp)
            return
        if not isinstance(comp, Comp):
            raise TypeError(
                f"add([...]) expects components or tag strings, got {comp!r}"
            )
        self._comps[comp.id] = comp
        comp.add(self)

    def use_all(self, comp_list):
        for c in comp_list:
            self.use(c)

    def has(self, comp_id: str) -> bool:
        return comp_id in self._comps

    def comp(self, comp_id: str):
        return self._comps.get(comp_id)

    # ---- kaplay-style attribute delegation ---------------------------------

    def __getattr__(self, name):
        # __getattr__ only fires when normal attribute lookup fails,
        # so this never shadows things set in __init__/__dict__.
        comps = self.__dict__.get("_comps", {})
        for c in comps.values():
            if hasattr(c, name):
                return getattr(c, name)
        raise AttributeError(
            f"GameObj has no attribute '{name}' — "
            f"did you forget a component that provides it?"
        )

    def __setattr__(self, name, value):
        # Allow plain-assignment mutation of component fields, e.g.
        # player.flipX = True (Lesson 6). Only redirect if the name is
        # not one of GameObj's own declared fields and a component owns it.
        if name.startswith("_") or name in (
            "tags", "children", "parent",
        ):
            object.__setattr__(self, name, value)
            return
        comps = self.__dict__.get("_comps")
        if comps:
            for c in comps.values():
                if hasattr(c, name):
                    # Refuse to replace a component's METHOD with a value.
                    # `rock.size = 3` looks like storing a number on your own
                    # object; it actually overwrites circle()'s size() method,
                    # and the game then dies somewhere else entirely with
                    # "'int' object is not callable" — in the collision system,
                    # nowhere near the line that did it. Found by writing
                    # examples/asteroids.py and losing a while to exactly that.
                    if callable(getattr(c, name)) and not callable(value):
                        raise AttributeError(
                            f"'{name}' is a method that {type(c).__name__} "
                            f"gives this object, so assigning to it would "
                            f"break the component. Pick another name for your "
                            f"own value — rock.{name}_value, or something "
                            f"that says what it is."
                        )
                    setattr(c, name, value)
                    return
        object.__setattr__(self, name, value)

    # ---- tree ---------------------------------------------------------------

    def add(self, comp_list):
        """Add a child object. Children are positioned/drawn relative to
        their parent and moved along with it (Lesson 8)."""
        child = GameObj(comp_list)
        child.parent = self
        child._engine = self._engine
        self.children.append(child)
        if self._engine:
            self._engine._register(child)
        return child

    def destroy(self):
        if self._destroyed:
            return
        self._destroyed = True
        for c in list(self._comps.values()):
            c.destroy(self)
        for child in list(self.children):
            child.destroy()
        if self.parent:
            try:
                self.parent.children.remove(self)
            except ValueError:
                pass
        if self._engine:
            self._engine._unregister(self)

    def exists(self) -> bool:
        return not self._destroyed

    def is_(self, tag: str) -> bool:
        return tag in self.tags

    # ---- events (mirrors the free onX functions, but scoped to this obj) --

    def _on(self, event, tag_or_fn, fn=None):
        if fn is None:
            handler = tag_or_fn
            tag = None
        else:
            tag = tag_or_fn
            handler = fn
        self._event_handlers.setdefault(event, []).append((tag, handler))
        return handler

    # Each of these takes a function, or is used as a decorator over one:
    #     player.onCollide("coin", pick_up)
    #     @player.onCollide("coin")
    #     def pick_up(coin): ...
    # See callutil.register_or_decorate for why both forms exist.

    def onUpdate(self, fn=None):
        from .callutil import register_or_decorate
        return register_or_decorate(fn, lambda f: self._on("update", f))

    def onClick(self, fn=None):
        if not self.has("area"):
            raise RuntimeError("onClick() needs area() on this object")
        from .callutil import register_or_decorate
        return register_or_decorate(fn, lambda f: self._on("click", f))

    def onCollide(self, tag, fn=None):
        if not self.has("area"):
            raise RuntimeError("onCollide() needs area() on this object")
        from .callutil import register_or_decorate
        return register_or_decorate(fn, lambda f: self._on("collide", tag, f))

    def onCollideUpdate(self, tag, fn=None):
        if not self.has("area"):
            raise RuntimeError("onCollideUpdate() needs area() on this object")
        from .callutil import register_or_decorate
        return register_or_decorate(fn, lambda f: self._on("collideUpdate", tag, f))

    def onCollideEnd(self, tag, fn=None):
        if not self.has("area"):
            raise RuntimeError("onCollideEnd() needs area() on this object")
        from .callutil import register_or_decorate
        return register_or_decorate(fn, lambda f: self._on("collideEnd", tag, f))

    def _fire(self, event, tag=None, *args):
        from .callutil import call_flexible
        for h_tag, handler in list(self._event_handlers.get(event, [])):
            if h_tag is None or h_tag == tag:
                call_flexible(handler, *args)

geometry.py:
"""Shared geometry helpers used by both collision (area()) and rendering,
so 'does this touch that' and 'where does this draw' never disagree."""
import pygame
from .vec2 import Vec2


def get_size(obj):
    if obj.has("sprite"):
        base = obj.comp("sprite").size()
    elif obj.has("rect"):
        base = obj.comp("rect").size()
    elif obj.has("circle"):
        base = obj.comp("circle").size()
    elif obj.has("text"):
        base = obj.comp("text").size()
    else:
        base = (0, 0)
    if obj.has("scale"):
        sc = obj.comp("scale").scale
        base = (base[0] * sc.x, base[1] * sc.y)
    return base


def get_world_pos(obj) -> Vec2:
    """Position in world space, folding in parent offsets (children are
    positioned relative to their parent, and move when it moves)."""
    p = obj.comp("pos").pos if obj.has("pos") else Vec2(0, 0)
    if obj.parent is not None:
        return p + get_world_pos(obj.parent)
    return p


def get_topleft(obj) -> Vec2:
    p = get_world_pos(obj)
    w, h = get_size(obj)
    if obj.has("anchor"):
        a = obj.comp("anchor").anchor
    else:
        # "Without it, pos() means the top-left corner."
        a = Vec2(-1, -1)
    offset_x = (a.x + 1) / 2 * w
    offset_y = (a.y + 1) / 2 * h
    return Vec2(p.x - offset_x, p.y - offset_y)


def get_world_rect(obj) -> "pygame.FRect":
    """Float-precision rect, used for collision. AABB resolution snaps
    resting objects to sub-pixel contact, and pygame.Rect truncates to
    ints — enough to make a resting object's ground contact flicker in
    and out of existence one pixel at a time. FRect avoids that."""
    tl = get_topleft(obj)
    w, h = get_size(obj)
    return pygame.FRect(tl.x, tl.y, max(w, 0), max(h, 0))

helpers.py:
"""The small Kaplay names — the ones a copied example reaches for.

None of these is load-bearing on its own. Together they are the difference
between a Kaplay example found on the internet running as written and failing
on its third line with a NameError, which is the thing kaypy exists to avoid:
"KAPLAY's documentation still tells you what to write" is only true while the
names in it exist.

Every one is Kaplay's own name with Kaplay's own arguments and its own return
type. Where Kaplay is loose about types — `rgb()` taking three numbers or one
hex string — that looseness is copied too, because a student pasting an
example should not have to know which spelling their source used.
"""
import math
import random as _random


def time():
    """Seconds since kaplay() started. Kaplay's clock, not the wall clock.

    Pauses when the game does, which is the whole point of not using
    `time.time()` — a sine wave driven by wall time jumps when a game is
    paused and resumed.
    """
    from .engine import current_engine
    return current_engine().elapsed()


def destroy(obj):
    """Remove one object. `obj.destroy()` does the same thing."""
    if obj is not None and hasattr(obj, "destroy"):
        obj.destroy()


def destroyAll(tag):
    """Remove every object carrying a tag. Returns how many went."""
    from .engine import current_engine
    doomed = current_engine().get(tag)
    for obj in doomed:
        obj.destroy()
    return len(doomed)


def isKeyDown(key):
    """Is this key held right now?

    The polling counterpart to `onKeyDown`. Some logic reads better asked
    than answered: `if isKeyDown("shift")` inside a handler you already have,
    rather than a second handler that sets a flag.
    """
    import pygame
    from .events import resolve_key

    try:
        return bool(pygame.key.get_pressed()[resolve_key(key)])
    except (KeyError, IndexError, pygame.error):
        return False


def rgb(r=255, g=None, b=None):
    """A colour, as a plain (r, g, b) tuple.

    Kaplay takes three numbers or one hex string, so this does too:
    `rgb(255, 128, 0)`, `rgb("#ff8800")`, `rgb("#f80")`, or `rgb(200)` for a
    grey. Two numbers is not a colour anyone meant, so it says so rather than
    inventing the third.
    """
    if isinstance(r, str):
        text = r.lstrip("#")
        if len(text) == 3:
            text = "".join(c * 2 for c in text)
        if len(text) != 6:
            raise ValueError(
                "rgb(%r): a hex colour looks like '#ff8800' or '#f80'" % r)
        try:
            return tuple(int(text[i:i + 2], 16) for i in (0, 2, 4))
        except ValueError:
            raise ValueError(
                "rgb(%r): that is not hex — try '#ff8800'" % r) from None
    if isinstance(r, (tuple, list)):
        return tuple(int(c) for c in r)[:3]
    if g is None and b is None:
        return (int(r), int(r), int(r))          # rgb(200) is a grey
    if b is None:
        raise ValueError(
            "rgb() takes three numbers, one hex string, or one number for a "
            "grey — rgb(%r, %r) is missing the blue." % (r, g))
    return (int(r), int(g), int(b))


def lerp(a, b, t):
    """Blend from a to b. Works on numbers and on vec2."""
    from .vec2 import Vec2

    if isinstance(a, Vec2) or isinstance(b, Vec2):
        return Vec2(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t)
    return a + (b - a) * t


def clamp(value, low, high):
    """Keep a number inside a range. Tolerates the bounds being swapped."""
    if low > high:
        low, high = high, low
    return max(low, min(high, value))


def chance(probability):
    """True that often. `chance(0.2)` is true one time in five."""
    return _random.random() < probability


def wave(low, high, t, func=math.sin):
    """A value swinging between low and high, forever.

        y = wave(100, 200, time() * 2)

    Kaplay's own signature. The fourth argument lets you swap the shape of
    the swing; `math.cos` starts at the top instead of the middle.
    """
    return low + (func(t) + 1) / 2 * (high - low)


def deg2rad(degrees):
    return math.radians(degrees)


def rad2deg(radians):
    return math.degrees(radians)

level.py:
"""addLevel(): draw a map as a picture made of characters. Each entry in
tiles is a function returning a component list — called once per tile,
so every tile gets its own object rather than all sharing one."""
from .vec2 import Vec2, vec2
from .comps.pos import pos as pos_comp


class Level:
    def __init__(self, config):
        self.tileWidth = config.get("tileWidth", 64)
        self.tileHeight = config.get("tileHeight", 64)
        origin = config.get("pos", Vec2(0, 0))
        self.origin = origin if isinstance(origin, Vec2) else vec2(*origin)
        self.objs = []

    def tile2Pos(self, col, row) -> Vec2:
        return Vec2(
            self.origin.x + col * self.tileWidth,
            self.origin.y + row * self.tileHeight,
        )

    def get(self, tag):
        return [o for o in self.objs if o.exists() and o.is_(tag)]


def addLevel(layout, config):
    from .engine import current_engine
    engine = current_engine()
    level = Level(config)
    tiles_map = config.get("tiles", {})

    for row_idx, row_str in enumerate(layout):
        for col_idx, ch in enumerate(row_str):
            if ch == " ":
                continue
            maker = tiles_map.get(ch)
            if maker is None:
                continue
            comp_list = maker()
            p = level.tile2Pos(col_idx, row_idx)
            obj = engine.add([pos_comp(p.x, p.y), *comp_list])
            level.objs.append(obj)

    return level

timers.py:
"""Kaplay's own timers (wait/loop) — tied to the frame loop, so they
pause and resume with the game, unlike Python's own time functions."""
from .callutil import call_flexible


class _Timer:
    def __init__(self, delay, fn, repeat):
        self.delay = delay
        self.fn = fn
        self.repeat = repeat
        self.elapsed = 0.0
        self.dead = False

    def cancel(self):
        self.dead = True


def _lerp(a, b, t):
    """Blend two values. Numbers, Vec2s and colour tuples all tween.

    A tween is almost always moving one of those three, and requiring a
    student to know which is which would be a worse lesson than the tween.
    """
    from .vec2 import Vec2

    if isinstance(a, Vec2) or isinstance(b, Vec2):
        return Vec2(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t)
    if isinstance(a, (tuple, list)):
        return type(a)(x + (y - x) * t for x, y in zip(a, b))
    return a + (b - a) * t


class Tween:
    """What `tween()` hands back: a handle on something still happening.

    `.then(fn)` runs something after it, `.cancel()` stops it where it is,
    `.finish()` jumps it to the end, and `.paused` holds it. All four are
    Kaplay's own names, so its documentation applies.
    """

    def __init__(self, start, end, duration, setter, ease):
        self.start = start
        self.end = end
        self.duration = float(duration)
        self.setter = setter
        self.ease = ease
        self.elapsed = 0.0
        self.paused = False
        self.dead = False
        self._ends = []

    def onEnd(self, fn):
        self._ends.append(fn)
        return self

    #: Kaplay spells this `then`, and it chains.
    then = onEnd

    def cancel(self):
        """Stop it where it is. Nothing further is set and onEnd never runs."""
        self.dead = True

    def finish(self):
        """Jump straight to the end value, and run the onEnd handlers."""
        if self.dead:
            return
        self.dead = True
        self.setter(self.end)
        self._fire()

    def _fire(self):
        for fn in self._ends:
            call_flexible(fn)

    def update(self, dt):
        if self.dead or self.paused:
            return
        self.elapsed += dt
        # A zero-length tween is an instant set, not a division by zero.
        progress = 1.0 if self.duration <= 0 else min(self.elapsed / self.duration, 1.0)
        self.setter(_lerp(self.start, self.end, self.ease(progress)))
        if progress >= 1.0:
            self.dead = True
            # Land exactly on the end value. An eased curve can return
            # 0.9999999 at t=1, and a sprite that stops one pixel short of
            # where it was told to go is a bug nobody can see but everybody
            # can feel.
            self.setter(self.end)
            self._fire()


class TimerManager:
    def __init__(self):
        self._timers = []
        self._tweens = []

    def wait(self, seconds, fn):
        t = _Timer(seconds, fn, repeat=False)
        self._timers.append(t)
        return t

    def loop(self, seconds, fn):
        t = _Timer(seconds, fn, repeat=True)
        self._timers.append(t)
        return t

    def tween(self, start, end, duration, setter, ease=None):
        from .easings import easings as _easings

        t = Tween(start, end, duration, setter, ease or _easings.linear)
        self._tweens.append(t)
        return t

    def update(self, dt):
        for t in list(self._timers):
            if t.dead:
                continue
            t.elapsed += dt
            if t.elapsed >= t.delay:
                t.elapsed -= t.delay
                if t.repeat:
                    call_flexible(t.fn)
                else:
                    t.dead = True
                    call_flexible(t.fn)
        self._timers = [t for t in self._timers if not t.dead]

        for t in list(self._tweens):
            t.update(dt)
        self._tweens = [t for t in self._tweens if not t.dead]

    def clear(self):
        self._timers.clear()
        self._tweens.clear()


def wait(seconds, fn):
    from .engine import current_engine
    return current_engine().timers.wait(seconds, fn)


def loop(seconds, fn):
    from .engine import current_engine
    return current_engine().timers.loop(seconds, fn)

vec2.py:
"""2D vector, matching Kaplay's vec2()."""
from __future__ import annotations
import math


class Vec2:
    __slots__ = ("x", "y")

    def __init__(self, x=0.0, y=0.0):
        self.x = float(x)
        self.y = float(y)

    def __repr__(self):
        return f"vec2({self.x:g}, {self.y:g})"

    def __iter__(self):
        yield self.x
        yield self.y

    def __eq__(self, other):
        if isinstance(other, Vec2):
            return self.x == other.x and self.y == other.y
        return NotImplemented

    def __add__(self, other):
        other = _coerce(other)
        return Vec2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        other = _coerce(other)
        return Vec2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        if isinstance(scalar, Vec2):
            return Vec2(self.x * scalar.x, self.y * scalar.y)
        return Vec2(self.x * scalar, self.y * scalar)

    __rmul__ = __mul__

    def __truediv__(self, scalar):
        if isinstance(scalar, Vec2):
            return Vec2(self.x / scalar.x, self.y / scalar.y)
        return Vec2(self.x / scalar, self.y / scalar)

    def __neg__(self):
        return Vec2(-self.x, -self.y)

    # Kaplay-style methods (camelCase, called as .sub()/.add()/.scale() too)
    def add(self, other):
        return self + other

    def sub(self, other):
        return self - other

    def scale(self, s):
        return self * s

    def dot(self, other):
        other = _coerce(other)
        return self.x * other.x + self.y * other.y

    def dist(self, other):
        other = _coerce(other)
        return math.hypot(self.x - other.x, self.y - other.y)

    def len(self):
        return math.hypot(self.x, self.y)

    def unit(self):
        length = self.len()
        if length == 0:
            return Vec2(0, 0)
        return Vec2(self.x / length, self.y / length)

    @classmethod
    def fromAngle(cls, degrees):
        """A unit vector pointing `degrees` clockwise from the +x axis.

        The partner to `rotate()`: an object at `angle` is facing
        `Vec2.fromAngle(obj.angle)`, so thrusting a ship forward is

            player.move(Vec2.fromAngle(player.angle) * SPEED)

        rather than trigonometry in the middle of a lesson. Clockwise for the
        same reason rotate() is — the screen's y axis points down — and it is
        the exact inverse of `.angle()`, which is checked in tests/test_rotate.py.
        """
        rad = math.radians(degrees)
        return cls(math.cos(rad), math.sin(rad))

    def angle(self, other=None):
        if other is None:
            return math.degrees(math.atan2(self.y, self.x))
        other = _coerce(other)
        return math.degrees(math.atan2(other.y - self.y, other.x - self.x))

    def lerp(self, other, t):
        other = _coerce(other)
        return Vec2(self.x + (other.x - self.x) * t, self.y + (other.y - self.y) * t)

    def clone(self):
        return Vec2(self.x, self.y)

    def to_tuple(self):
        return (self.x, self.y)


def _coerce(v):
    if isinstance(v, Vec2):
        return v
    if isinstance(v, (tuple, list)) and len(v) == 2:
        return Vec2(v[0], v[1])
    if isinstance(v, (int, float)):
        return Vec2(v, v)
    raise TypeError(f"expected vec2-like, got {v!r}")


_UNSET = object()


def vec2(x=0.0, y=_UNSET):
    """kaplay's vec2(x, y). Also accepts vec2(vec2), vec2((x, y)), and vec2(n) for (n, n)."""
    if isinstance(x, Vec2):
        return Vec2(x.x, x.y)
    if isinstance(x, (tuple, list)) and len(x) == 2:
        return Vec2(x[0], x[1])
    if y is _UNSET:
        # single number: vec2(n) -> (n, n)
        return Vec2(x, x)
    return Vec2(x, y)

