"""area(): the collision box. Both objects in a collision need one —
an object without area() is invisible to collision, and that's the
single most common reason a collision "doesn't work"."""
from ..gameobj import Comp


class AreaComp(Comp):
    id = "area"

    def add(self, obj):
        self._obj = obj

    def get_rect(self):
        from ..geometry import get_world_rect
        return get_world_rect(self._obj)

    def isHovering(self) -> bool:
        from ..engine import current_engine
        mx, my = current_engine().mousePos()
        return self.get_rect().collidepoint(mx, my)


def area():
    return AreaComp()

comps/body.py:
"""body(): makes an object respond to physics. isStatic=True makes it a
wall — solid, and never moved by anything. mass=n makes it heavy but
still pushable. Gives .jump(), .isGrounded(), .onGround()."""
from ..gameobj import Comp
from ..vec2 import Vec2


class BodyComp(Comp):
    id = "body"

    def __init__(self, isStatic=False, mass=1, jumpForce=800):
        self.isStatic = isStatic
        self.mass = mass
        self.jumpForce = jumpForce
        self.vel = Vec2(0, 0)
        self._grounded = False
        self._pending_grounded = False
        self._ground_handlers = []

    def add(self, obj):
        self._obj = obj

    def jump(self, force=None):
        if force is None:
            force = self.jumpForce
        self.vel.y = -force
        self._grounded = False

    def isGrounded(self) -> bool:
        return self._grounded

    def onGround(self, fn=None):
        from ..callutil import register_or_decorate

        def register(f):
            self._ground_handlers.append(f)
            return f

        return register_or_decorate(fn, register)

    def _apply_grounded(self, value: bool):
        was = self._grounded
        self._grounded = value
        if value and not was:
            for fn in self._ground_handlers:
                fn()


def body(isStatic=False, mass=1, jumpForce=800):
    return BodyComp(isStatic=isStatic, mass=mass, jumpForce=jumpForce)

comps/move.py:
"""move(dir, speed): drifts an object in a straight line forever.
offscreen(destroy=True): cleans it up once it leaves the screen.
tile(isObstacle=): marks an object as occupying a square on a grid."""
from ..gameobj import Comp
from ..vec2 import vec2, Vec2


class MoveComp(Comp):
    id = "move"

    def __init__(self, direction, speed):
        if isinstance(direction, Vec2):
            self.direction = direction.unit()
        else:
            self.direction = vec2(*direction).unit()
        self.speed = speed

    def add(self, obj):
        self._obj = obj

    def update(self, obj):
        if obj.has("pos"):
            obj.comp("pos").move(self.direction * self.speed)


def move(direction, speed):
    return MoveComp(direction, speed)


class OffscreenComp(Comp):
    id = "offscreen"

    def __init__(self, destroy=False, distance=64):
        self.destroy = destroy
        self.distance = distance

    def add(self, obj):
        self._obj = obj

    def update(self, obj):
        from ..engine import current_engine
        from ..geometry import get_world_pos
        engine = current_engine()
        p = get_world_pos(obj)
        d = self.distance
        if (p.x < -d or p.x > engine.width() + d or
                p.y < -d or p.y > engine.height() + d):
            if self.destroy:
                obj.destroy()


def offscreen(destroy=False, distance=64):
    return OffscreenComp(destroy=destroy, distance=distance)


class TileComp(Comp):
    id = "tile"

    def __init__(self, isObstacle=False):
        self.isObstacle = isObstacle

    def add(self, obj):
        self._obj = obj


def tile(isObstacle=False):
    return TileComp(isObstacle=isObstacle)

