"""Drawable shape/text components: rect(), circle(), text().
These hold data only — the RenderSystem does the actual drawing so
z-ordering, camera transform, anchor and scale stay in one place."""
from ..gameobj import Comp


class RectComp(Comp):
    id = "rect"

    def __init__(self, width, height, radius=0):
        self.width = width
        self.height = height
        self.radius = radius

    def size(self):
        return (self.width, self.height)


def rect(width, height, radius=0):
    return RectComp(width, height, radius)


class CircleComp(Comp):
    id = "circle"

    def __init__(self, radius):
        self.radius = radius

    def size(self):
        d = self.radius * 2
        return (d, d)


def circle(radius):
    return CircleComp(radius)


class TextComp(Comp):
    id = "text"

    def __init__(self, text_str="", size=22, width=None):
        self.text = text_str
        self.textSize = size
        self.width = width
        self._font_cache_key = None
        self._surf_cache = None
        self._surf_cache_key = None

    def render_surface(self, color=(255, 255, 255)):
        from ..engine import current_engine
        import pygame
        font = current_engine()._get_font(self.textSize)
        key = (self.text, self.textSize, self.width, color)
        if self._surf_cache_key == key:
            return self._surf_cache
        if self.width:
            surf = _wrap_text(font, self.text, self.width, color)
        else:
            surf = font.render(self.text, True, color)
        self._surf_cache_key = key
        self._surf_cache = surf
        return surf

    def size(self):
        return self.render_surface().get_size()


def _wrap_text(font, text_str, max_width, color):
    import pygame
    words = text_str.split(" ")
    lines = []
    current = ""
    for word in words:
        trial = (current + " " + word).strip()
        if font.size(trial)[0] > max_width and current:
            lines.append(current)
            current = word
        else:
            current = trial
    if current:
        lines.append(current)
    if not lines:
        lines = [""]
    line_surfs = [font.render(line, True, color) for line in lines]
    total_h = sum(s.get_height() for s in line_surfs)
    total_w = max((s.get_width() for s in line_surfs), default=0)
    out = pygame.Surface((max(total_w, 1), max(total_h, 1)), pygame.SRCALPHA)
    y = 0
    for s in line_surfs:
        out.blit(s, (0, y))
        y += s.get_height()
    return out


def text(text_str="", size=22, width=None):
    return TextComp(text_str, size=size, width=width)

comps/sprite.py:
import pygame
from ..gameobj import Comp


class SpriteComp(Comp):
    id = "sprite"

    def __init__(self, name, anim=None, frame=None):
        self.spriteName = name
        self.flipX = False
        self.flipY = False
        self._asset = None
        self._frame_override = frame
        self._cur_anim = None
        self._anim_spec = None
        self._anim_frame_idx = 0
        self._anim_timer = 0.0
        self._anim_done = False
        self._pending_initial_anim = anim
        self._frame_cache = {}

    def add(self, obj):
        from ..engine import current_engine
        self._asset = current_engine().assets.get_sprite(self.spriteName)
        if self._frame_override is None:
            self._anim_frame_idx = 0
        if self._pending_initial_anim:
            self.play(self._pending_initial_anim)

    def play(self, name):
        """Restarts the animation from its first frame — calling it every
        frame while a key is held gives a character stuck on frame 0."""
        spec = self._asset.anims.get(name)
        if spec is None:
            raise KeyError(
                f"sprite {self.spriteName!r} has no animation called {name!r}"
            )
        self._cur_anim = name
        self._anim_spec = spec
        self._anim_frame_idx = spec["from"]
        self._anim_timer = 0.0
        self._anim_done = False

    def curAnim(self):
        return self._cur_anim

    def update(self, obj):
        if self._cur_anim is None or self._anim_done:
            return
        from ..engine import current_engine
        dt = current_engine().dt()
        spec = self._anim_spec
        speed = spec.get("speed") or 10
        step = 1.0 / speed
        self._anim_timer += dt
        while self._anim_timer >= step:
            self._anim_timer -= step
            if self._anim_frame_idx >= spec["to"]:
                if spec.get("loop"):
                    self._anim_frame_idx = spec["from"]
                else:
                    self._anim_done = True
                    break
            else:
                self._anim_frame_idx += 1

    def current_surface(self):
        idx = self._frame_override if self._frame_override is not None else self._anim_frame_idx
        frames = self._asset.frames
        idx = max(0, min(idx, len(frames) - 1))
        key = (idx, self.flipX, self.flipY)
        cached = self._frame_cache.get(key)
        if cached is not None:
            return cached
        surf = frames[idx]
        if self.flipX or self.flipY:
            surf = pygame.transform.flip(surf, self.flipX, self.flipY)
        self._frame_cache[key] = surf
        return surf

    def size(self):
        return self._asset.frame_size


def sprite(name, anim=None, frame=None):
    return SpriteComp(name, anim=anim, frame=frame)

comps/state.py:
"""state(): gives an object a mode (idle, attack, move...) and different
behaviour in each — how nearly all simple game AI is written."""
from ..gameobj import Comp


class StateComp(Comp):
    id = "state"

    def __init__(self, start, states):
        self.states = list(states)
        if start not in self.states:
            raise ValueError(f"state() start {start!r} not in {self.states!r}")
        self._state = start
        self._enter_handlers = {}
        self._update_handlers = {}
        self._entered_once = False

    def add(self, obj):
        self._obj = obj

    def onStateEnter(self, name, fn=None):
        from ..callutil import register_or_decorate
        self._check(name)

        def register(f):
            self._enter_handlers.setdefault(name, []).append(f)
            return f

        return register_or_decorate(fn, register)

    def onStateUpdate(self, name, fn=None):
        from ..callutil import register_or_decorate
        self._check(name)

        def register(f):
            self._update_handlers.setdefault(name, []).append(f)
            return f

        return register_or_decorate(fn, register)

    def enterState(self, name):
        self._check(name)
        self._state = name
        for fn in self._enter_handlers.get(name, []):
            fn()

    def state_name(self):
        return self._state

    def update(self, obj):
        if not self._entered_once:
            # fire the starting state's onStateEnter handlers once, the
            # first frame this object exists.
            self._entered_once = True
            for fn in self._enter_handlers.get(self._state, []):
                fn()
        for fn in self._update_handlers.get(self._state, []):
            fn()

    def _check(self, name):
        if name not in self.states:
            raise ValueError(f"{name!r} is not one of this object's states {self.states!r}")


def state(start, states):
    return StateComp(start, states)

comps/transform.py:
"""Small appearance/behavior components: anchor, scale, rotate, color,
opacity, outline, z, fixed()."""
from ..gameobj import Comp
from ..vec2 import Vec2, vec2

_ANCHOR_NAMES = {
    "topleft": (-1, -1), "top": (0, -1), "topright": (1, -1),
    "left": (-1, 0), "center": (0, 0), "right": (1, 0),
    "botleft": (-1, 1), "bot": (0, 1), "botright": (1, 1),
}


class AnchorComp(Comp):
    id = "anchor"

    def __init__(self, value):
        self.anchor = self._resolve(value)

    def _resolve(self, value):
        if isinstance(value, str):
            if value not in _ANCHOR_NAMES:
                raise ValueError(f"unknown anchor name {value!r}")
            x, y = _ANCHOR_NAMES[value]
            return Vec2(x, y)
        if isinstance(value, Vec2):
            return value
        raise TypeError(
            "anchor() takes a name like anchor(\"center\") or an offset "
            "vec2(x, y) between -1 and 1 — not a screen position"
        )


def anchor(value):
    return AnchorComp(value)


class ScaleComp(Comp):
    id = "scale"

    def __init__(self, x=1, y=None):
        if y is None:
            y = x
        self.scale = Vec2(x, y)


def scale(x=1, y=None):
    return ScaleComp(x, y)


class RotateComp(Comp):
    """rotate(degrees) — turn the object, clockwise, about its anchor.

    Clockwise because the screen's y axis points down, so a positive angle
    turns the way a clock does, which is what anyone drawing on a screen
    expects. Asteroids is the reason this exists: a ship that cannot turn
    is not a ship.

    The **collision box does not turn with it**, deliberately. It stays the
    upright rectangle the object would have had at angle 0, which is what
    Kaplay does too. A rotating box whose hitbox rotated with it would grow
    and shrink twice a revolution, so an asteroid spinning on the spot would
    catch the player at some angles and not others — a bug nobody would ever
    guess at from the symptom.
    """

    id = "rotate"

    def __init__(self, angle=0):
        self.angle = angle

    def rotateBy(self, degrees):
        """Turn by this much more. `obj.rotateBy(180 * dt())` in onUpdate."""
        self.angle += degrees
        return self.angle

    def rotateTo(self, degrees):
        """Face exactly this way."""
        self.angle = degrees
        return self.angle


def rotate(angle=0):
    return RotateComp(angle)


class ColorComp(Comp):
    id = "color"

    def __init__(self, r=255, g=255, b=255):
        self.color = (r, g, b)


def color(r=255, g=255, b=255):
    return ColorComp(r, g, b)


class OpacityComp(Comp):
    id = "opacity"

    def __init__(self, n=1.0):
        self.opacity = n


def opacity(n=1.0):
    return OpacityComp(n)


class OutlineComp(Comp):
    id = "outline"

    def __init__(self, width=1, color=(0, 0, 0)):
        self.outlineWidth = width
        self.outlineColor = color


def outline(width=1, color=(0, 0, 0)):
    return OutlineComp(width, color)


class ZComp(Comp):
    id = "z"

    def __init__(self, z=0):
        self.z = z


def z(value=0):
    return ZComp(value)


class FixedComp(Comp):
    """Marks an object as ignoring the camera (stays put on screen)."""
    id = "fixed"

    def __init__(self):
        self.fixed = True


def fixed():
    return FixedComp()
